import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, useLocation, useNavigate } from 'react-router-dom';

// AUTH
import Login from './components/Clients/Auth/Login';
import Register from './components/Clients/Auth/Register';
import ProtectedRoute from './components/Clients/Auth/ProtectedRoute';

// LAYOUTS
import Dashboard from './components/DashboardLayout';
import ClientLayout from './components/ClientLayout';

// CLIENT PAGES
import Home from './components/Clients/Home/Home';
import Services from './components/Clients/Services/Services';
import Portfolio from './components/Clients/Portfolio/Portfolio';
import Contact from './components/Clients/Contact/Contact';
import Messages from './components/Clients/Messages/Messages'; // Assure-toi de l'importer

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState(null);
  const [currentUser, setCurrentUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    const userData = localStorage.getItem('userData');
    const authToken = localStorage.getItem('authToken');

    if (userData && authToken) {
      try {
        const user = JSON.parse(userData);
        const formattedUser = {
          ...user,
          email: user.email || '',
          first_name: user.first_name || user.name || user.email?.split('@')[0] || 'Utilisateur',
          role: user.role || 'user'
        };
        setCurrentUser(formattedUser);
        setUserRole(formattedUser.role);
        setIsAuthenticated(true);

        // Redirection automatique
        if (formattedUser.role === 'admin' && !location.pathname.startsWith('/admin')) {
          navigate('/admin', { replace: true });
        } else if (formattedUser.role === 'user' && location.pathname.startsWith('/admin')) {
          navigate('/', { replace: true });
        }
      } catch (error) {
        console.error('Erreur parsing userData:', error);
        handleLogout();
      }
    }
    setIsLoading(false);
  }, [location.pathname, navigate]);

  const handleLogin = (userData, token) => {
    const formattedUser = {
      ...userData,
      email: userData.email || '',
      first_name: userData.first_name || userData.name || userData.email?.split('@')[0] || 'Utilisateur',
      role: userData.role || 'user'
    };

    localStorage.setItem('userData', JSON.stringify(formattedUser));
    localStorage.setItem('authToken', token);

    setCurrentUser(formattedUser);
    setUserRole(formattedUser.role);
    setIsAuthenticated(true);

    navigate(formattedUser.role === 'admin' ? '/admin' : '/', { replace: true });
  };

  const handleLogout = () => {
    localStorage.removeItem('userData');
    localStorage.removeItem('authToken');
    setCurrentUser(null);
    setUserRole(null);
    setIsAuthenticated(false);
    navigate('/login', { replace: true });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white dark:bg-neutral-950">
        <div className="text-center">
          <div className="h-12 w-12 border-4 border-primary-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
          <p className="mt-4 text-neutral-600 dark:text-neutral-400">Chargement...</p>
        </div>
      </div>
    );
  }

  return (
    <Routes>
      {/* LOGIN */}
      <Route
        path="/login"
        element={
          isAuthenticated ? (
            <Navigate to={userRole === 'admin' ? '/admin' : '/'} replace />
          ) : (
            <ClientLayout isAuthenticated={isAuthenticated} onLogout={handleLogout} currentUser={currentUser}>
              <Login onLogin={handleLogin} />
            </ClientLayout>
          )
        }
      />

      {/* REGISTER */}
      <Route
        path="/register"
        element={
          isAuthenticated ? (
            <Navigate to={userRole === 'admin' ? '/admin' : '/'} replace />
          ) : (
            <ClientLayout isAuthenticated={isAuthenticated} onLogout={handleLogout} currentUser={currentUser}>
              <Register onLogin={handleLogin} />
            </ClientLayout>
          )
        }
      />

      {/* DASHBOARD ADMIN */}
      <Route
        path="/admin/*"
        element={
          <ProtectedRoute isAuthenticated={isAuthenticated} requiredRole="admin" userRole={userRole}>
            <Dashboard onLogout={handleLogout} currentUser={currentUser} />
          </ProtectedRoute>
        }
      />

      {/* ROUTES CLIENT */}
      <Route path="/" element={<ClientLayout isAuthenticated={isAuthenticated} onLogout={handleLogout} currentUser={currentUser} />}>
        <Route index element={<Home currentUser={currentUser} />} />
        <Route path="services" element={<Services />} />
        <Route path="portfolio" element={<Portfolio />} />
        <Route path="contact" element={<Contact />} />
        <Route
          path="messages"
          element={
            <ProtectedRoute isAuthenticated={isAuthenticated} requiredRole="user" userRole={userRole}>
              <Messages />
            </ProtectedRoute>
          }
        />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Route>
    </Routes>
  );
}

export default function AppWrapper() {
  return (
    <Router>
      <App />
    </Router>
  );
}
